function renderHealth(){if(!activeFight)return;$('objective-timer').hidden=!activeFight.objectiveMode;$('objective-timer').value=activeFight.time;$('objective-status').hidden=!activeFight.objectiveMode;$('objective-status').textContent=activeFight.objectiveMode?objectiveStatus(activeFight):'';if(activeFight.mode==='team')return renderTeamHud();for(const [i,id]of ['fighter-a','fighter-b'].entries()){const f=activeFight.fighters[i],card=$(id),track=node('div','','health-track'),fill=node('div','','health-fill');fill.style.width=Math.max(0,f.hp/f.maxHp*100)+'%';track.append(fill);card.replaceChildren(node('strong',f.name),node('span',f.actionLabel||'','fighter-action'),track,node('span',`${Math.ceil(f.hp)} / ${Math.ceil(f.maxHp)} HP`),node('div',`${Math.floor(f.mana)} mana · ${Math.round(f.energy??100)} stamina · ${f.weapon.name}`,'mana'));}$('fight-clock').textContent=activeFight.time.toFixed(1)+'s / 90s';}
