 const path=count<2?'Select at least two fighters to see recommendations.':plan.some(r=>!r.settingsValid)?'Check the stage settings to preview your full tournament.':`${count} fighters → ${plan.map((r,i)=>i===plan.length-1?'1 champion':config[i].type==='swiss'?'~'+r.outgoing:r.outgoing).join(' → ')}`;
