  const tip=stageTips[i];if(!tip)return;
  tip.root.hidden=count<2;
  tip.flow.textContent=r.active?`${r.incoming} fighters in · ${i===config.length-1?'1 champion':r.settingsValid?(config[i].type==='swiss'?'all three-win fighters advance (about '+r.outgoing+')':r.outgoing+' advance'):'check settings'}`:'Waiting for valid settings in the previous stage.';
