  tip.suggestion.textContent=r.active?suggestionText(r.suggestion,i):'';
  const changed=r.active&&['groups','rounds','advance'].some(k=>(k==='advance'?i<config.length-1&&config[i].type!=='swiss':k==='groups'?config[i].type==='groups':config[i].type==='swiss')&&config[i][k]!==r.suggestion[k]);
