function readFilters(){return normalizeFilters({style:$('filter-style').value||'any',tier:$('filter-tier').value||'any',rank:$('filter-rank').value||'any'});}
function renderEntrants(){const selected=new Set([...$('entrants').querySelectorAll('input:checked')].map(e=>e.value)),filters=readFilters(),key=divisionKey(filters),eligible=roster.filter(c=>matchesFilters(c,filters));$('entrants').replaceChildren();for(const c of eligible){const label=node('label','','entrant'),check=node('input');check.type='checkbox';check.value=c.id;check.checked=selected.has(c.id);check.addEventListener('change',updateSelectedCount);const text=node('span',c.name),meta=node('span',` ${tierFor(c.summary.total)} · ${c.summary.total} pts`,'entrant-info');if(champions.some(x=>x.divisionKey===key&&x.characterId===c.id)){const crown=node('span',' 👑','champion-mark');crown.setAttribute('aria-label',divisionLabel(filters)+' current champion');crown.title=divisionLabel(filters)+' current champion';text.append(crown);}text.append(meta);label.append(check,text);$('entrants').append(label);}$('filter-count').textContent=`${eligible.length} / ${roster.length} characters eligible · ${divisionLabel(readFilters())}`;updateSelectedCount();}
async function refreshChampions(){try{const data=await api('champions');champions=(data.champions||[]).filter(c=>c.divisionKey!=='latest');championRecords=data.records||[];championshipHistory=data.history||[];championshipDivisions=data.divisions||[];$('champion-list').replaceChildren();if(!champions.length)$('champion-list').append(node('p','Finish a tournament to crown its champion.','muted'));for(const title of champions){const card=node('div','','champion-card'),text=node('div');text.append(node('strong',roster.find(c=>c.id===title.characterId)?.name||title.characterName),node('small',title.label),node('small',`${title.titles||1}× Champion of ${title.cupLabel||title.label}`));if(title.currentStreak>=2)text.append(node('span',`${title.currentStreak} in a row 🔥`,'win-streak'));text.append(node('small',title.tournamentName));card.append(node('span','👑','crown'),text);$('champion-list').append(card);}const selected=$('history-division').value;$('history-division').replaceChildren(option('all','All cups'));for(const cup of championshipDivisions)$('history-division').append(option(cup.divisionKey,cup.label));$('history-division').value=championshipDivisions.some(c=>c.divisionKey===selected)?selected:'all';renderChampionHistory();renderEntrants();renderArenaCollection();}catch(e){$('champion-list').replaceChildren(node('p',e.message,'muted'));}}
function renderChampionHistory(){const key=$('history-division').value||'all',records=championRecords.filter(r=>key==='all'||r.divisionKey===key),events=championshipHistory.filter(r=>key==='all'||r.divisionKey===key);$('history-summary').textContent=events.length?(n=>`${events.length} completed tournament${events.length===1?'':'s'} · ${n} champion${n===1?'':'s'}`)(new Set(records.map(r=>r.characterId)).size):'No completed tournaments in this cup yet.';$('history-records').replaceChildren();for(const r of records){const card=node('article','','history-record');card.append(node('strong',roster.find(c=>c.id===r.characterId)?.name||r.characterName),node('p',`${r.titles}× Champion of ${r.label}`));if(r.currentStreak>=2)card.append(node('span',`${r.currentStreak} in a row 🔥`,'win-streak'));card.append(node('small',`Best streak: ${r.bestStreak}${r.currentStreak?' · Current champion':''}`));$('history-records').append(card);}$('history-events').replaceChildren();for(const e of events){const card=node('div','','history-event');card.append(node('strong',e.characterName),node('span',`${e.tournamentName} · ${e.label}`),node('time',new Date(e.completedAt).toLocaleString()));$('history-events').append(card);}}
function renderCurrentBracket(){if(!tournament)return;const chosen=bracketStage===null?tournament.stageIndex:bracketStage;const select=$('bracket-stage');select.replaceChildren();tournament.stages.forEach((s,i)=>select.append(option(String(i),`${i+1}. ${FORMATS[s.type]}`)));select.value=String(chosen);$('bracket-note').textContent=['single','double'].includes(tournament.stages[chosen].type)?'Gold: next match. Green: winner. Dashed lines: losses into the lower bracket. Select a completed match to replay.': 'Round pairings and scores. Swiss future pairings are drawn after each round. Select a completed match to replay.';renderBracket($('bracket-visual'),tournament,chosen);}

function readConditions(prefix){return normalizeConditions({time:$(prefix+'-night').value||'day',weather:$(prefix+'-weather').value||'clear',ground:$(prefix+'-ground').value||'stone'});}
function renderAbilityReference(){const root=$('ability-reference');root.replaceChildren();for(const [heading,entries]of [['Abilities',Object.entries(POWERS).map(([name,p])=>[name+' · '+p.rarity+' '+p.kind,p.description])],['Weaknesses',Object.entries(WEAKNESSES)]]){root.append(node('h3',heading));const list=node('dl');for(const [name,text]of entries){list.append(node('dt',name),node('dd',text));}root.append(list);}root.append(node('p','Silver longswords and revolvers use silver. Cold-iron spears use cold iron. Poisoned daggers and blowguns apply poison. Blessed maces deal holy damage. These variants keep their corresponding base weapon scores.','muted'));}
function drawEnvironment(){const b=activeFight;if(!b.environment)return;for(const z of b.zones||[]){ctx.save();ctx.globalAlpha=.24;const spriteIndex={fire:0,lava:0,shadow:11,gravity:4,life:12,bramble:8,seedburst:8}[z.type];sprite('effects',spriteIndex,z.x,z.y,z.radius*2,0,.25);ctx.strokeStyle=['life','bramble','seedburst'].includes(z.type)?'#96d7a5':z.type==='gravity'?'#ad88d6':'#b57862';ctx.lineWidth=1;ctx.beginPath();ctx.arc(z.x,z.y,z.radius,0,Math.PI*2);ctx.stroke();ctx.restore();}for(const o of b.obstacles||[])if(o.terrain)drawRock(o);else sprite('effects',8,o.x,o.y,o.radius*2+5);for(const f of b.fighters){if(f.illusionTime>0&&f.decoy?.hp>0){ctx.fillStyle=teamOf(f)?'#ff5a6a80':'#3ee0ff80';ctx.beginPath();ctx.arc(f.decoy.x,f.decoy.y,9,0,Math.PI*2);ctx.fill();}if(f.portalTime>0&&f.gates)for(const gate of f.gates)sprite('effects',15,gate.x,gate.y,30);if(f.soul>0){const owner=b.fighters[f.soulOwner];ctx.strokeStyle='#9871c5';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(owner.x,owner.y);ctx.lineTo(f.x,f.y);ctx.stroke();}if(f.flight>0||f.foreseen>0||f.wardHits>0)sprite('effects',f.flight>0?7:f.foreseen>0?10:14,f.x,f.y,30,0,.45);}for(const s of b.summons||[])sprite('effects',s.type==='spirit'?4:7,s.x,s.y,s.type==='spirit'?13:16);for(const w of b.wisps||[]){if(w.hp<=0)continue;ctx.fillStyle='#d4e4c5';ctx.beginPath();ctx.arc(w.x,w.y,4,0,Math.PI*2);ctx.fill();}for(const food of b.food||[]){if(food.ready>b.time)continue;ctx.strokeStyle='#9cc578';ctx.strokeRect(food.x-4,food.y-4,8,8);}if(b.relic?.active){sprite('effects',4,b.relic.x,b.relic.y,28,0,.5);ctx.strokeStyle='#ad86d548';ctx.lineWidth=1;ctx.beginPath();ctx.arc(b.relic.x,b.relic.y,b.relic.radius,0,Math.PI*2);ctx.stroke();}if(['rain','storm'].includes(b.environment.weather)){ctx.strokeStyle='#b9d5e52a';ctx.lineWidth=1;const {W,H}=fieldView();for(let i=0;i<Math.round(40*W*H/360000);i++){const x=(i*137+b.time*25)%W,y=(i*73+b.time*95)%H;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y+9);ctx.stroke();}}if(b.environment.weather==='frost'){const {W,H}=fieldView();ctx.strokeStyle='#b0d5e925';ctx.strokeRect(13,13,W-26,H-26);}}
// Map terrain: shaded stone pillars that block movement, projectiles and line of sight.
function drawRock(o){ctx.save();const g=ctx.createRadialGradient(o.x-o.radius*.35,o.y-o.radius*.4,o.radius*.15,o.x,o.y,o.radius);if(g?.addColorStop){g.addColorStop(0,'#6a7488');g.addColorStop(.6,'#3a4150');g.addColorStop(1,'#1c2029');ctx.fillStyle=g;}else ctx.fillStyle='#3a4150';ctx.shadowColor='#000000b0';ctx.shadowBlur=10;ctx.beginPath();ctx.arc(o.x,o.y,o.radius,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#9fb0c855';ctx.lineWidth=1.5;ctx.stroke();ctx.restore();}

function freshTournamentName(){suggestedName=randomTournamentName(tournamentNames);$('tourney-name').value=suggestedName;nameEdited=false;}

function updateSelectedCount(){const n=$('entrants').querySelectorAll('input:checked').length;$('selected-count').textContent=n+' selected';updateStageAdvice();}
function setArenaView(view){if(view==='history')mode('history');else if(arenaMode==='history')mode(previousArenaMode);document.body.dataset.arenaView=view;for(const name of ['setup','live','history'])$('mobile-'+name).setAttribute('aria-pressed',String(name===view));}
for(const name of ['setup','live','history'])$('mobile-'+name).addEventListener('click',()=>{setArenaView(name);if(name==='history')refreshChampions();});
$('history-division').addEventListener('change',renderChampionHistory);
if(matchMedia('(max-width: 800px)').matches){$('profile-a-details').open=false;$('profile-b-details').open=false;}

function renderArenaCollection(){const filterKey=JSON.stringify(['collection-order','collection-min-winrate','collection-min-titles'].map(id=>$(id).value));if(filterKey!==arenaFilterKey){arenaFilterKey=filterKey;arenaVisibleLimit=80;}
 $('arena-saved-count').textContent=String(roster.length);if(!$('arena-collection').open)return;
 const characters=ROSTER_VIEW.select(roster,{order:$('collection-order').value,minWinRate:$('collection-min-winrate').value,minTitles:$('collection-min-titles').value},championRecords),list=$('arena-saved-list');
 $('collection-visible').textContent=`${characters.length} / ${roster.length} characters`;list.replaceChildren();
 for(const c of characters.slice(0,arenaVisibleLimit)){
  const card=node('article','','saved-card'),heading=node('div','','saved-card-heading'),badge=node('span',tierFor(c.summary.total),'tier-badge');badge.setAttribute('data-tier',tierFor(c.summary.total));heading.append(node('h3',c.name),badge);
  const rarity=c.summary.wheelRarity||'common',origin=node('span',rarity[0].toUpperCase()+rarity.slice(1)+' wheel','wheel-origin');origin.setAttribute('data-wheel-rarity',rarity);card.setAttribute('data-wheel-rarity',rarity);
  card.append(heading,origin,node('p',[c.summary.subrace,c.summary.race,c.summary.class].filter(Boolean).join(' · '),'saved-details'),node('p',`${c.summary.total} points · ${c.summary.rank}`,'saved-score'));
  if(c.summary.growth||c.summary.promotion)card.append(node('p',globalThis.ROSTER_VIEW.growthText(c),'earned-growth'));
  const crownText=ROSTER_VIEW.currentChampionText(c,champions);if(crownText)card.append(node('p',crownText,'champion-titles'));
  if(c.leagueMember)card.append(node('p',c.leagueMember.name+' · protected league member','saved-details'));
  const rate=ROSTER_VIEW.winRate(c),r=c.matchRecord||{wins:0,losses:0,draws:0,matches:0};card.append(node('p',`${r.wins} W · ${r.losses} L${r.draws?' · '+r.draws+' D':''} · ${r.matches} matches · ${rate===null?'Unplayed':rate.toFixed(1)+'% wins'}`,'fighter-record'),ROSTER_VIEW.championshipDetails(c,championRecords));
  const details=node('details'),body=node('div','','profile');details.append(node('summary','Stats & traits'));
  const tap=(key,text)=>{const button=node('button',text,'trait-tap');button.type='button';button.addEventListener('click',()=>guard(async()=>inspectCharacter(await character(c.id),key)));return button;};
  const stats=node('div','','detail-stat-buttons');c.summary.stats.forEach((v,i)=>stats.append(tap(STAT_KEYS[i],STAT_KEYS[i]+' '+v)));body.append(stats);
  for(const [label,key]of [['Weapon','weapon'],['Ability','power'],['Second ability','power2'],['Weakness','weakness']])if(c.traits?.[key]){const line=node('div','','trait');line.append(tap(key,`${label}: ${c.traits[key]}`));body.append(line);}details.append(body);card.append(details);
  const actions=node('div','','saved-actions');const detailButton=node('button','Details','button secondary');detailButton.type='button';detailButton.addEventListener('click',()=>guard(async()=>inspectCharacter(await character(c.id))));actions.append(detailButton);for(const side of ['a','b']){const button=node('button','Use as fighter '+side.toUpperCase(),'button secondary');button.disabled=!!series||resolving;button.addEventListener('click',()=>guard(async()=>{$('choose-'+side).value=c.id;mode(false);setArenaView('setup');$('arena-collection').close();await showProfile(side);}));actions.append(button);}card.append(actions);list.append(card);
 }
 if(characters.length>arenaVisibleLimit){const more=node('button',`Show more (${Math.min(arenaVisibleLimit,characters.length)} / ${characters.length})`,'button secondary');more.type='button';more.onclick=()=>{arenaVisibleLimit+=80;renderArenaCollection();};list.append(more);}
}
$('open-arena-collection').onclick=()=>{$('arena-collection').showModal();renderArenaCollection();guard(refreshRoster);};$('close-arena-collection').onclick=()=>$('arena-collection').close();$('refresh-arena-collection').onclick=()=>guard(refreshRoster);
$('collection-order').addEventListener('change',renderArenaCollection);for(const id of ['collection-min-winrate','collection-min-titles'])$(id).addEventListener('input',renderArenaCollection);$('collection-clear').onclick=()=>{$('collection-min-winrate').value='';$('collection-min-titles').value='';renderArenaCollection();};

BULK_CHARACTERS.mount($('collection-bulk'),{
 roster:()=>roster,
 start:()=>{if(series||resolving||saving||bulkBusy||leagueBusy)throw new Error('Wait until the current fight or save finishes.');bulkBusy=true;updateButtons();},
 finish:()=>{bulkBusy=false;updateButtons();},
 change:({roster:all,characters,deletedIds})=>{
  if(all)roster=all;
  if(characters){const incoming=new Set(characters.map(c=>c.id));roster=[...characters,...roster.filter(c=>!incoming.has(c.id))];}
  if(deletedIds){const removed=new Set(deletedIds);roster=roster.filter(c=>!removed.has(c.id));}
  loaded.clear();profileContributions.clear();for(const c of roster)if(c.traits)loaded.set(c.id,compact(c));
  $('arena-saved-count').textContent=String(roster.length);
  if(all){for(const id of ['choose-a','choose-b']){const old=$(id).value;$(id).replaceChildren(option('','Choose a saved character'));for(const c of roster)$(id).append(option(c.id,`${c.name} · ${tierFor(c.summary.total)}`));$(id).value=roster.some(c=>c.id===old)?old:'';}renderArenaCollection();renderEntrants();guard(()=>Promise.all([showProfile('a'),showProfile('b')]));updateButtons();}
 }
});

const leagueUI=mountLeagues($('league-panel'),{blocked:()=>!!series||resolving||bulkBusy||saving,busy:value=>{leagueBusy=value;updateButtons();},trophies:c=>ROSTER_VIEW.championshipDetails(c,championRecords),refresh:refreshRoster,watch:async(a,b,format,conditions,environments)=>{await loadReplayEngine(format.engineVersion??13);return new Promise((resolve,reject)=>{try{beginSeries(a,b,format,format.seed,conditions,!environments&&!format.allowDraw,'League series',resolve,format.engineVersion??13,environments);}catch(e){reject(e);}});}});
